model Task {
  id: ID
  title: String min=1
  done: Bool = false
}

api tasks: Task

component TaskItem(task: Task, onToggle: Fn, onRemove: Fn) {
  row gap=2 align=center {
    checkbox task.done -> onToggle(task)
    text task.title muted=task.done
    button "x" small danger -> onRemove(task.id)
  }
}

page Home "/" {
  state draft = ""
  data tasks = api.tasks.list()
  computed pending = tasks.filter(t => !t.done)

  fn add() {
    if draft.trim() == "" { return }
    api.tasks.create({ title: draft.trim() })
    draft = ""
  }

  fn toggle(t) {
    api.tasks.update(t.id, { done: t.done })
  }

  fn remove(id) {
    api.tasks.remove(id)
  }

  column gap=4 {
    title "Lista de tareas"
    row gap=2 {
      input draft placeholder="¿Qué hay que hacer?" -> add()
      button "Agregar" primary -> add()
    }
    if tasks.length == 0 {
      text "No hay tareas" muted
    } else {
      for t in tasks key t.id {
        TaskItem task=t onToggle=(x => toggle(x)) onRemove=(id => remove(id))
      }
      text `${pending.length} pendientes` small
    }
  }
}

