page Home "/" {
  state draft = ""
  state tasks: Any[] = []
  state nextId = 1
  computed pending = tasks.filter(t => !t.done)

  fn add() {
    let title = draft.trim()
    if title == "" { return }
    tasks = [...tasks, { id: nextId, title: title, done: false }]
    nextId = nextId + 1
    draft = ""
  }

  fn toggle(t) {
    tasks = [...tasks]
  }

  fn remove(id) {
    tasks = tasks.filter(t => t.id != id)
  }

  column gap=4 {
    title "Lista de tareas"
    row gap=2 {
      input draft placeholder="¿Qué hay que hacer?" -> add()
      button "Agregar" primary -> add()
    }
    if tasks.length == 0 {
      text "No hay tareas" muted
    } else {
      for t in tasks key t.id {
        TaskItem task=t onToggle=(x => toggle(x)) onRemove=(id => remove(id))
      }
      text `${pending.length} pendientes` small
    }
  }
}

