page Login "/" {
  state email = ""
  state password = ""
  state logged = false
  computed valid = email.includes("@") && password.length >= 8

  fn submit() {
    if !valid { return }
    logged = true
  }

  column gap=4 pad=4 {
    if logged {
      title `Bienvenido, ${email}`
    } else {
      title "Iniciar sesión"
      form gap=2 -> submit() {
        input email type="email" label="Email" placeholder="tu@correo.com" required
        input password type="password" label="Contraseña" placeholder="Mínimo 8 caracteres" required
        button "Entrar" primary disabled=(!valid)
      }
    }
  }
}

