model CartItem {
  id: Number
  name: String
  price: Number
  qty: Number
}

page Shop "/" {
  state products: Any[] = [
    { id: 1, name: "Remera", price: 19.99 },
    { id: 2, name: "Gorra", price: 9.5 },
    { id: 3, name: "Zapatillas", price: 59.9 }
  ]
  state cart: Any[] = []

  computed total = cart.reduce((sum, i) => sum + i.price * i.qty, 0)
  computed totalText = total.toFixed(2)

  fn add(p) {
    let found = cart.find(i => i.id == p.id)
    if found {
      cart = cart.map(i => i.id == p.id ? { ...i, qty: i.qty + 1 } : i)
    } else {
      cart = [...cart, { id: p.id, name: p.name, price: p.price, qty: 1 }]
    }
  }

  fn change(id, delta) {
    cart = cart
      .map(i => i.id == id ? { ...i, qty: i.qty + delta } : i)
      .filter(i => i.qty > 0)
  }

  column gap=4 pad=4 {
    title "Tienda"
    column gap=2 {
      for p in products key p.id {
        row gap=2 align=center {
          text p.name bold
          text `$${p.price.toFixed(2)}` muted
          button "Agregar" primary small -> add(p)
        }
      }
    }
    divider
    title "Carrito"
    if cart.length == 0 {
      text "El carrito está vacío" muted
    } else {
      column gap=2 {
        for i in cart key i.id {
          row gap=2 align=center {
            text i.name
            button "-" small -> change(i.id, -1)
            text `${i.qty}`
            button "+" small -> change(i.id, 1)
            text `$${(i.price * i.qty).toFixed(2)}` muted
          }
        }
      }
    }
    text `Total: $${totalText}` bold large
  }
}

