page Counter "/" {
  state count = 0
  computed double = count * 2
  fn inc() {
    if count < 10 {
      count++
    }
  }
  fn dec() {
    if count > 0 {
      count--
    }
  }
  fn reset() {
    count = 0
  }

  column gap=4 align=center {
    title "Contador"
    row gap=2 {
      button "-" -> dec()
      text count bold
      button "+" primary -> inc()
    }
    button "Reset" small -> reset()
    text `El doble es ${double}` muted
    if count > 5 {
      text "¡Más de 5!"
    }
  }
}

