export type Ball = { x: number; y: number; vx: number; vy: number; r: number }

const W = 400
const H = 300
const R = 10
const G = 0.2

export function make(): Ball {
  return {
    x: R + Math.random() * (W - 2 * R),
    y: R + Math.random() * (H - 2 * R),
    vx: (Math.random() * 2 - 1) * 4 || 1,
    vy: (Math.random() * 2 - 1) * 4,
    r: R,
  }
}

function clamp(b: Ball) {
  if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx) }
  if (b.x > W - b.r) { b.x = W - b.r; b.vx = -Math.abs(b.vx) }
  if (b.y < b.r) { b.y = b.r; b.vy = Math.abs(b.vy) }
  if (b.y > H - b.r) { b.y = H - b.r; b.vy = -Math.abs(b.vy) }
}

export function step(balls: Ball[]) {
  for (const b of balls) {
    b.vy += G
    b.x += b.vx
    b.y += b.vy
    clamp(b)
  }
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i]
      const c = balls[j]
      const dx = c.x - a.x
      const dy = c.y - a.y
      const min = a.r + c.r
      const d2 = dx * dx + dy * dy
      if (d2 <= min * min) {
        let d = Math.sqrt(d2)
        let nx: number
        let ny: number
        if (d === 0) { nx = 1; ny = 0; d = 0 } else { nx = dx / d; ny = dy / d }
        // separar
        const overlap = min - d
        a.x -= nx * overlap / 2
        a.y -= ny * overlap / 2
        c.x += nx * overlap / 2
        c.y += ny * overlap / 2
        // intercambio de velocidades (elástica, masas iguales) sólo si se acercan
        const rvx = a.vx - c.vx
        const rvy = a.vy - c.vy
        if (rvx * nx + rvy * ny > 0) {
          const tx = a.vx
          const ty = a.vy
          a.vx = c.vx
          a.vy = c.vy
          c.vx = tx
          c.vy = ty
        }
        clamp(a)
        clamp(c)
      }
    }
  }
}

export function draw(cv: HTMLCanvasElement | null, balls: Ball[]) {
  if (!cv) return
  const ctx = cv.getContext("2d")
  if (!ctx) return
  ctx.clearRect(0, 0, W, H)
  ctx.fillStyle = "#3b82f6"
  for (const b of balls) {
    ctx.beginPath()
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
    ctx.fill()
  }
}

