export type Ball = { x: number; y: number; vx: number; vy: number; r: number };

const W = 400;
const H = 300;
const R = 10;

export function make(): Ball {
  return {
    x: R + Math.random() * (W - 2 * R),
    y: R + Math.random() * (H - 2 * R),
    vx: (Math.random() - 0.5) * 6,
    vy: (Math.random() - 0.5) * 6,
    r: R,
  };
}

export function step(balls: Ball[]): void {
  for (const b of balls) {
    b.vy += 0.2;
    b.x += b.vx;
    b.y += b.vy;
    if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx); }
    if (b.x > W - b.r) { b.x = W - b.r; b.vx = -Math.abs(b.vx); }
    if (b.y < b.r) { b.y = b.r; b.vy = Math.abs(b.vy); }
    if (b.y > H - b.r) { b.y = H - b.r; b.vy = -Math.abs(b.vy); }
  }

  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const b = balls[j];
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const minD = a.r + b.r;
      const d2 = dx * dx + dy * dy;
      if (d2 > minD * minD) continue;
      let d = Math.sqrt(d2);
      let nx: number;
      let ny: number;
      if (d === 0) {
        nx = 1; ny = 0; d = 0;
      } else {
        nx = dx / d; ny = dy / d;
      }
      // separar para que no queden superpuestas
      const overlap = minD - d;
      a.x -= (nx * overlap) / 2;
      a.y -= (ny * overlap) / 2;
      b.x += (nx * overlap) / 2;
      b.y += (ny * overlap) / 2;
      // mantener dentro de los bordes
      for (const p of [a, b]) {
        p.x = Math.min(W - p.r, Math.max(p.r, p.x));
        p.y = Math.min(H - p.r, Math.max(p.r, p.y));
      }
      // elástica con masas iguales: intercambio de la componente normal
      const van = a.vx * nx + a.vy * ny;
      const vbn = b.vx * nx + b.vy * ny;
      if (van - vbn > 0) {
        const diff = vbn - van;
        a.vx += diff * nx;
        a.vy += diff * ny;
        b.vx -= diff * nx;
        b.vy -= diff * ny;
      }
    }
  }
}

export function draw(cv: HTMLCanvasElement | null, balls: Ball[]): void {
  if (!cv) return;
  const ctx = cv.getContext("2d");
  if (!ctx) return;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = "#f5f5f5";
  ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = "#3b82f6";
  for (const b of balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fill();
  }
}

