    { id: 1, text: "Comprar pan" },
    { id: 2, text: "Llamar a Ana" },
    { id: 3, text: "Pagar luz" }
  ]
  state edited = 0

  fn update(id, v) {
    let current = notes.find(n => n.id == id)
    if !current { return }
    if v != current.text {
      notes = notes.map(n => n.id == id ? { id: n.id, text: v } : n)
      edited = edited + 1
    }
  }

  column gap=3 pad=4 {
    title "Notas"
    for n in notes key n.id {
      Note value=n.text onSave=(v => update(n.id, v))
    }
    text `Editadas: ${edited}`
  }
}

component Note(value: String, onSave: Fn) {
  state editing = false
  state draft = ""

  fn start() {
    draft = value
    editing = true
  }
  fn save() {
    onSave(draft)
    editing = false
  }
  fn cancel() {
    editing = false
  }

  row gap=2 align=center {
    if editing {
      input draft -> save()
      button "Guardar" primary small -> save()
      button "Cancelar" small -> cancel()
    } else {
      text value
      button "Editar" small -> start()
    }
  }
}

page Home "/" {
  state notes: String[] = ["Comprar pan", "Llamar a Ana", "Pagar luz"]
  state edited = 0

  fn update(i, v) {
    if v != notes[i] {
      notes[i] = v
      edited++
    }
  }

  column gap=3 pad=4 {
    title "Notas"
    column gap=2 {
      for n, i in notes key i {
        Note value=n onSave=(v => update(i, v))
      }
    }
    text `Editadas: ${edited}`
  }
}

model Task {
  id: ID
  title: String min=1
  done: Bool = false
}

api tasks: Task

page Home "/" {
  state draft = ""
  state filter = "Todas"
  state editingId = ""
  state newTitle = ""
  data tasks = api.tasks.list()
  computed visible = tasks.filter(t => filter == "Todas" || (filter == "Pendientes" && !t.done) || (filter == "Hechas" && t.done))

  fn add() {
    if draft.trim() == "" { return }
    api.tasks.create({ title: draft.trim() })
    draft = ""
  }
  fn startEdit(t) {
    editingId = t.id
    newTitle = t.title
  }
  fn save(t) {
    if newTitle.trim() == "" { return }
    api.tasks.update(t.id, { title: newTitle.trim() })
    editingId = ""
    newTitle = ""
  }

  column gap=4 {
    title "Tareas"
    row gap=2 {
      input draft placeholder="Tarea" -> add()
      button "Agregar" primary -> add()
    }
    select filter options=["Todas", "Pendientes", "Hechas"] label="Filtro"
    for t in visible key t.id {
      row gap=2 align=center {
        if editingId == t.id {
          input newTitle placeholder="Nuevo título" -> save(t)
          button "Guardar" primary -> save(t)
        } else {
          text t.title
          if t.done {
            text "(hecha)" muted
          } else {
            button "Hecha" small -> api.tasks.update(t.id, { done: true })
          }
          button "Renombrar" small -> startEdit(t)
        }
      }
    }
  }
}

