model Vote {
  id: ID
  choice: String min=1
}

api votes: Vote

server fn results() {
  let all = db.votes.list()
  let dogs = all.filter(v => v.choice == "dogs").length
  let cats = all.filter(v => v.choice == "cats").length
  let total = dogs + cats
  return {
    dogs: dogs,
    cats: cats,
    dogsPct: total == 0 ? 0 : Math.round(dogs * 100 / total),
    catsPct: total == 0 ? 0 : Math.round(cats * 100 / total)
  }
}

server fn vote(choice) {
  if choice != "dogs" && choice != "cats" {
    fail("Opción inválida")
  }
  db.votes.create({ choice: choice })
  return true
}

server fn reset() {
  let all = db.votes.list()
  for v of all {
    db.votes.remove(v.id)
  }
  return true
}

page Home "/" {
  state stats = { dogs: 0, cats: 0, dogsPct: 0, catsPct: 0 }

  fn refresh() {
    server.results().then(r => { stats = r })
  }

  fn castVote(choice) {
    server.vote(choice).then(() => refresh())
  }

  fn clearAll() {
    server.reset().then(() => refresh())
  }

  mount {
    refresh()
  }

  column gap=4 pad=4 {
    title "Encuesta: ¿Perros o Gatos?"
    row gap=2 {
      button "Votar Perros" primary -> castVote("dogs")
      button "Votar Gatos" primary -> castVote("cats")
    }
    text `Perros: ${stats.dogsPct}% (${stats.dogs} votos)`
    text `Gatos: ${stats.catsPct}% (${stats.cats} votos)`
    button "Reiniciar" danger -> clearAll()
  }
}

