model Product {
  id: ID
  name: String min=1
  number: Number
}

api products: Product

server fn seed() {
  let n = await db.products.count()
  if n > 0 { return false }
  for (let i = 1; i <= 12; i++) {
    await db.products.create({ name: `Producto ${i}`, number: i })
  }
  return true
}

page Catalog "/" {
  state query = ""
  state page = 0
  state items: Product[] = []
  state total = 0

  fn load(q, p) {
    api.products.list({ search: q, sort: "number", limit: 5, offset: p * 5 }).then(r => { items = r })
    api.products.count({ search: q }).then(c => { total = c })
  }

  effect { load(query, page) }

  fn loadExamples() {
    server.seed().then(() => load(query, page))
  }

  fn next() {
    if (page + 1) * 5 < total { page = page + 1 }
  }

  fn prev() {
    if page > 0 { page = page - 1 }
  }

  column gap=4 pad=4 {
    title "Catálogo"
    button "Cargar ejemplos" primary -> loadExamples()
    input query placeholder="Buscar" on:input=(page = 0)
    text `Total: ${total}`
    list {
      for p in items key p.id {
        item p.name
      }
    }
    row gap=2 {
      button "Anterior" disabled=(page == 0) -> prev()
      button "Siguiente" disabled=((page + 1) * 5 >= total) -> next()
    }
  }
}

