model Product {
  id: ID
  name: String min=1
  number: Number
}

api products: Product

server fn seed() {
  let n = await db.products.count()
  if n > 0 { return false }
  for (let i = 1; i <= 12; i++) {
    await db.products.create({ name: `Producto ${i}`, number: i })
  }
  return true
}

server fn search(q, page) {
  let all = await db.products.list({ sort: "number", limit: 100000 })
  let term = (q ?? "").trim().toLowerCase()
  let matched = all.filter(p => p.name.toLowerCase().includes(term))
  matched.sort((a, b) => a.number - b.number)
  let start = page * 5
  return { items: matched.slice(start, start + 5), total: matched.length }
}

page Home "/" {
  state q = ""
  state page = 0
  state result: Any = { items: [], total: 0 }

  fn load() {
    server.search(q, page).then(r => { result = r })
  }

  fn loadExamples() {
    server.seed().then(() => {
      page = 0
      load()
    })
  }

  effect {
    let qq = q
    let pp = page
    server.search(qq, pp).then(r => { result = r })
  }

  column gap=4 pad=4 {
    title "Catálogo"
    button "Cargar ejemplos" primary -> loadExamples()
    input q placeholder="Buscar" on:input=(page = 0)
    text `Total: ${result.total}`
    list {
      for p in result.items key p.id {
        item p.name
      }
    }
    row gap=2 {
      button "Anterior" disabled=(page == 0) -> page = page - 1
      button "Siguiente" disabled=((page + 1) * 5 >= result.total) -> page = page + 1
    }
  }
}

