files.coupons.art:
component CouponsPage {
  state items: Item[] = [
    { id: 1, name: "Alfa", amount: 10, active: true },
    { id: 2, name: "Beta", amount: 20, active: true },
    { id: 3, name: "Gama", amount: 30, active: false }
  ]
  fn add(name, amount) {
    items.push({ id: Date.now(), name, amount, active: true })
  }
  fn remove(id) {
    items = items.filter(i => i.id != id)
  }

  column gap=2 {
    title "Cupones"
    CouponsForm onAdd=add
    CouponsList items=items onRemove=remove
  }
}

component CouponsList(items: Item[], onRemove: Any) {
  if items.length == 0 {
    text "Sin registros" muted
  } else {
    column gap=1 {
      for item in items {
        CouponsRow item=item onRemove=onRemove
      }
    }
  }
}

component CouponsRow(item: Item, onRemove: Any) {
  row gap=2 {
    text item.name bold
    text `Descuento: ${item.amount}`
    button "Eliminar" danger small -> onRemove(item.id)
  }
}

component CouponsForm(onAdd: Fn) {
  state name = ""
  state amount = 0
  fn submit() {
    onAdd(name, amount)
    name = ""
    amount = 0
  }

  row gap=2 {
    input name placeholder="Nombre"
    input amount placeholder="Descuento" type=number
    button "Agregar" primary -> submit()
